PRAGMA journal_mode = WAL;
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS profiles (id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS interests (name TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS profile_interests (profile_id TEXT REFERENCES profiles(id) ON DELETE CASCADE, interest TEXT REFERENCES interests(name), PRIMARY KEY(profile_id,interest));
CREATE TABLE IF NOT EXISTS posts (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, data TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS boards (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, data TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS board_items (board_id TEXT REFERENCES boards(id) ON DELETE CASCADE, post_id TEXT REFERENCES posts(id) ON DELETE CASCADE, created_at TEXT NOT NULL, PRIMARY KEY(board_id,post_id));
CREATE TABLE IF NOT EXISTS follows (profile_id TEXT REFERENCES profiles(id) ON DELETE CASCADE, target_id TEXT REFERENCES profiles(id) ON DELETE CASCADE, PRIMARY KEY(profile_id,target_id));
CREATE TABLE IF NOT EXISTS likes (profile_id TEXT REFERENCES profiles(id) ON DELETE CASCADE, post_id TEXT REFERENCES posts(id) ON DELETE CASCADE, PRIMARY KEY(profile_id,post_id));
CREATE TABLE IF NOT EXISTS comments (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE, text TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS conversations (id TEXT PRIMARY KEY, participant_a TEXT NOT NULL REFERENCES profiles(id), participant_b TEXT NOT NULL REFERENCES profiles(id), requested_by TEXT NOT NULL REFERENCES profiles(id), status TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(participant_a,participant_b));
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id), sender_id TEXT NOT NULL REFERENCES profiles(id), text TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS conversation_reads (conversation_id TEXT REFERENCES conversations(id), profile_id TEXT REFERENCES profiles(id), read_at TEXT NOT NULL, PRIMARY KEY(conversation_id,profile_id));
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), data TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS invitations (id TEXT PRIMARY KEY, from_id TEXT NOT NULL REFERENCES profiles(id), to_id TEXT NOT NULL REFERENCES profiles(id), status TEXT NOT NULL, match_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS matches (id TEXT PRIMARY KEY, participant_a TEXT NOT NULL REFERENCES profiles(id), participant_b TEXT NOT NULL REFERENCES profiles(id), data TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS moves (id TEXT PRIMARY KEY, match_id TEXT NOT NULL REFERENCES matches(id), profile_id TEXT NOT NULL REFERENCES profiles(id), round INTEGER NOT NULL, card_id TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(match_id,profile_id,round));
CREATE TABLE IF NOT EXISTS blocks (profile_id TEXT REFERENCES profiles(id), target_id TEXT REFERENCES profiles(id), created_at TEXT NOT NULL, PRIMARY KEY(profile_id,target_id));
CREATE TABLE IF NOT EXISTS reports (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), target_id TEXT NOT NULL REFERENCES profiles(id), reason TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_posts_created ON posts(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_posts_profile ON posts(profile_id);
CREATE INDEX IF NOT EXISTS idx_messages_conversation ON messages(conversation_id,created_at);
CREATE INDEX IF NOT EXISTS idx_notifications_profile ON notifications(profile_id);
CREATE INDEX IF NOT EXISTS idx_invitation_to ON invitations(to_id,status);
CREATE INDEX IF NOT EXISTS idx_moves_match ON moves(match_id,round);
